export const streamSimpleAnthropic: StreamFunction<"anthropic-messages", SimpleStreamOptions> = (
	model: Model<"anthropic-messages">,
	context: TranscriptContext,
	options?: SimpleStreamOptions,
): AssistantMessageEventStream => {
	context = asTranscriptContext(context);
	const apiKey = resolveVendoredAnthropicApiKey(options);
	if (!apiKey) {
		throw new Error(`No API key for provider: ${model.provider}`);
	}
	const thinkingDisplay = (options as (SimpleStreamOptions & {
		thinkingDisplay?: AnthropicThinkingDisplay;
	}) | undefined)?.thinkingDisplay;
	const base = {
		...buildBaseOptions(model, context, options, apiKey),
		...(thinkingDisplay === undefined ? {} : { thinkingDisplay }),
	} as AnthropicOptions;
	if (!options?.reasoning) {
		return streamAnthropic(model, context, { ...base, thinkingEnabled: false });
	}

	// For modern Claude 4.x adaptive models: use adaptive thinking with effort level
	// For older models: use budget-based thinking
	if (supportsAdaptiveThinking(model)) {
		const hasExplicitNullEffort =
			model.thinkingLevelMap !== undefined &&
			Object.prototype.hasOwnProperty.call(model.thinkingLevelMap, options.reasoning) &&
			model.thinkingLevelMap[options.reasoning] === null;
		return streamAnthropic(model, context, {
			...base,
			thinkingEnabled: true,
			effort: hasExplicitNullEffort
				? undefined
				: mapThinkingLevelToEffort(options.reasoning, model),
			...(hasExplicitNullEffort ? { thinkingDisplay: "omitted" as const } : {}),
		} satisfies AnthropicOptions);
	}

	const adjusted = adjustMaxTokensForThinking(
		base.maxTokens || 0,
		model.maxTokens,
		options.reasoning,
		options.thinkingBudgets,
	);

	const maxTokens = clampMaxTokensToContext(model, context, adjusted.maxTokens);
	const thinkingBudget = Math.min(adjusted.thinkingBudget, Math.max(0, maxTokens - 1024));
	return streamAnthropic(model, context, {
		...base,
		maxTokens,
		thinkingEnabled: thinkingBudget >= 1024,
		thinkingBudgetTokens: thinkingBudget,
	} satisfies AnthropicOptions);
};

export function isOAuthToken(apiKey: string): boolean {
	return apiKey.includes("sk-ant-oat");
}

function createClientWithFetch(
	model: Model<"anthropic-messages">,
	apiKey: string,
	interleavedThinking: boolean,
	optionsHeaders?: Record<string, string | null>,
	fetchImpl?: typeof fetch,
): { client: Anthropic; isOAuthToken: boolean } {
	const needsInterleavedBeta = interleavedThinking && !supportsAdaptiveThinking(model);
	const betaFeatures = ["fine-grained-tool-streaming-2025-05-14"];
	if (needsInterleavedBeta) {
		betaFeatures.push("interleaved-thinking-2025-05-14");
	}
	const fetch = withMessagesBetaQuery(fetchImpl ?? globalThis.fetch.bind(globalThis));

	if (isOAuthToken(apiKey)) {
		const client = new Anthropic({
			apiKey: null,
			authToken: apiKey,
			baseURL: model.baseUrl,
			fetch,
			dangerouslyAllowBrowser: true,
			defaultHeaders: mergeHeaders(
				{
					accept: "application/json",
					"anthropic-dangerous-direct-browser-access": "true",
					"anthropic-beta": `claude-code-20250219,oauth-2025-04-20,${betaFeatures.join(",")}`,
					"user-agent": `claude-cli/${claudeCodeVersion}`,
					"x-app": "cli",
				},
				model.headers,
				optionsHeaders,
			),
		});
		return { client, isOAuthToken: true };
	}

	const client = new Anthropic({
		apiKey,
		baseURL: model.baseUrl,
		fetch,
		dangerouslyAllowBrowser: true,
		defaultHeaders: mergeHeaders(
			{
				accept: "application/json",
				"anthropic-dangerous-direct-browser-access": "true",
				"anthropic-beta": betaFeatures.join(","),
			},
			model.headers,
			optionsHeaders,
		),
	});
	return { client, isOAuthToken: false };
}

export function createClient(
	model: Model<"anthropic-messages">,
	apiKey: string,
	interleavedThinking: boolean,
	optionsHeaders?: Record<string, string | null>,
): { client: Anthropic; isOAuthToken: boolean } {
	return createClientWithFetch(model, apiKey, interleavedThinking, optionsHeaders);
}

export function buildParams(
	model: Model<"anthropic-messages">,
	context: TranscriptContext,
	isOAuthToken: boolean,
	options?: AnthropicOptions,
	strictToolPolicy: { disablePreferredStrictTools?: boolean; hasPreferredStrictTools?: boolean } = {},
): MessageCreateParamsStreaming {
	context = resolveAnthropicTranscript(model, context);
	const { cacheControl } = getCacheControl(model, options?.cacheRetention, options?.env);
	const initialSystemMessage = getInitialSystemMessage(context.messages);
	const initialTools = initialSystemMessage?.toolsAdded ?? [];
	// Inline `tool_definition` blocks express same-name redefinitions, so redefinitions no
	// longer force the collapsed transcript. Beta resolution reuses this same decision.
	const nativeToolChanges = usesAnthropicCcNativeToolChanges(model, context);
	const initialSystemText = initialSystemMessage
		? getSystemMessageText(initialSystemMessage)
		: "";
	const conversationMessages = initialSystemMessage
		? context.messages.slice(1)
		: context.messages;
	const supportsMidConvoEffort = model.compat?.supportsMidConvoEffort === true;
	const usesActiveManagedEffort = recordsManagedEffortFor(model, options);
	const thinkingDisabled = isThinkingDisabled(model, options);
	const activeEffort = options?.effort ?? "high";
	const supportsStrictTools = model.compat?.supportsStrictTools === true;
	const convertRequestToolDefinitions = (tools: Tool[]) => {
		const definitions = convertToolsWithStrictMode(
			tools, isOAuthToken, supportsStrictTools, strictToolPolicy.disablePreferredStrictTools,
		);
		if (definitions.some((definition, index) => {
			const config = tools[index].constrainedSampling;
			return definition.strict === true && !!config && config.type === "json_schema" && config.strict === "prefer";
		})) strictToolPolicy.hasPreferredStrictTools = true;
		return definitions;
	};
	// Native tool changes define every later tool by value in a `tool_addition` block,
	// using the same strict-mode conversion and CC naming as top-level declarations.
	const convertToolDefinitions = nativeToolChanges ? convertRequestToolDefinitions : undefined;
	const messages = convertMessages(
		conversationMessages,
		model,
		isOAuthToken,
		cacheControl,
